// 取得所有資料字典
const data = $input.all().map(i => i.json || {});

// 抓取各個維度的報表資料
const risk = data.find(r => r.reportType === 'deal_risk') || {};
const rep = data.find(r => r.reportType === 'rep_kpi') || {};
const market = data.find(r => r.reportType === 'market') || {};

const reps = rep.reps || [];
const regions = market.regions || [];
const top_rep = reps.length > 0 ? reps[0] : null;

// 格式化當前時間 (YYYY-MM-DD HH:mm)
const now = new Date();
const dateStr = now.getFullYear() + '-' + 
                String(now.getMonth() + 1).padStart(2, '0') + '-' + 
                String(now.getDate()).padStart(2, '0') + ' ' + 
                String(now.getHours()).padStart(2, '0') + ':' + 
                String(now.getMinutes()).padStart(2, '0');

const lines = [
    '== 主管 Pipeline 戰情報告 ==',
    `報告時間：${dateStr}`,
    '',
    `高風險：${risk.totalRiskDeals || 0} 筆`,
    `已逾期：${risk.overdueDeals || 0} 筆`,
    '',
    '-- 業務排行 --'
];

// 處理業務排行 (前5名)，並加上千分位逗號
reps.slice(0, 5).forEach((r, i) => {
    lines.push(`${i + 1}. ${r.salesRep || 'Unknown'} — ${r.dealCount || 0}筆 加權$${Number(r.weightedAmount || 0).toLocaleString()}`);
});

lines.push('');
lines.push('-- 區域 --');
regions.forEach(r => {
    lines.push(`${r.region || 'Unknown'}：${r.dealCount || 0}筆 $${Number(r.weightedAmount || 0).toLocaleString()}`);
});

lines.push('');
lines.push('-- 建議 --');
lines.push((risk.totalRiskDeals || 0) > 5 ? '高風險超過5筆，建議召開 deal review' : '風險可控');
if (top_rep) {
    lines.push(`MVP：${top_rep.salesRep || 'Unknown'}`);
}

return [{
    json: {
        generatedAt: now.toISOString(),
        executiveReport: lines.join('\n'),
        detail: { risk, rep, market }
    }
}];
